INSERT OR IGNORE INTO material_catalog (id,curricular_unit_id,lesson_id,material_kind,bibliography_format,title,description,file_name,mime_type,storage_backend,storage_key,storage_state,byte_size,checksum_sha256,verification_status,publication_status,public_access,source_id,page_note,version_group,version_number,is_recommended,created_at,updated_at) SELECT 'material-biblio-2627-ap12-nolte6-translation',cu.id,'lesson-neuro-ap12','bibliography','translation','Nolte’s The Human Brain — AP12 · Tradução','Bibliografia traduzida para AP12. 67 páginas e 26 figuras numeradas, distribuídas por 32 páginas de figuras.','AP12_Nolte_Bibliografia_Traduzida_2026-10-10.pdf','application/pdf','r2','materials/neuroanatomia/bibliografia/traducoes/2026-27/AP12_Nolte_Bibliografia_Traduzida_2026-10-10.pdf','ready',10225059,'5bfd548ed59b4410c5cc45a73dba731e3d1667a013c8394214295725c027a85d','verified','published',0,'source-nolte-6','Nolte, 6.ª edição: pp. 342–345; 349–352; 358–361; 363–380.','biblio-2627-ap12-nolte6-translation',1,1,unixepoch()*1000,unixepoch()*1000 FROM curricular_units cu WHERE cu.code='NEURO' AND cu.active=1 AND EXISTS(SELECT 1 FROM material_sources WHERE id='source-nolte-6') AND EXISTS(SELECT 1 FROM material_lessons WHERE id='lesson-neuro-ap12');

INSERT OR IGNORE INTO material_catalog_lessons(material_id,lesson_id,relevance,sort_order) SELECT 'material-biblio-2627-ap12-nolte6-translation','lesson-neuro-ap12','primary',0 WHERE EXISTS(SELECT 1 FROM material_catalog WHERE id='material-biblio-2627-ap12-nolte6-translation');

INSERT INTO admin_audit_log(actor_user_id,action,details,created_at) SELECT id,'neuro_translation_published','{"batch":"approved-ap12-nolte-2026-10-10"}',unixepoch()*1000 FROM users WHERE status='active' AND commission_position='principal_admin' AND NOT EXISTS(SELECT 1 FROM admin_audit_log WHERE action='neuro_translation_published' AND details LIKE '%approved-ap12-nolte-2026-10-10%') LIMIT 1;
